    <div style="background:rgba(15,23,42,0.55);border-radius:10px;padding:12px 14px;margin-top:12px;">
    <p style="margin:0 0 4px 0;"><strong style="color:#bfdbfe;">🎯 Learning outcomes (CBC):</strong> By the end of the sub-strand, you should be able to:</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Identify the main idea and specific details in an argumentative text.</li>
    <li>Listen for the main idea and specific details in oral texts.</li>
    <li>Infer the meaning of unfamiliar words from context.</li>
    <li>Recognise the need for comprehension in communication.</li>
    </ul>
    <p style="margin:8px 0 4px 0;"><strong style="color:#bfdbfe;">🏁 Lesson objectives:</strong> By the end of this lesson, you should be able to:</p>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Identify details of time, place, events, people and numbers.</li>
    <li>Use a listening grid to record details.</li>
    <li>Explain how details support the main idea.</li>
    <li>Answer detail questions accurately.</li>
    </ul>
    <p style="margin:8px 0 0 0;"><strong style="color:#bfdbfe;">❓ Key inquiry question:</strong> How do the specific details in a text enhance comprehension?</p>
    <p style="margin:8px 0 0 0;"><strong style="color:#bfdbfe;">🧰 What you already know:</strong> Lesson 1.3.1 — listening for the main idea.</p>
    </div>
